"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Marker } from "@/components/ui/marker"
import { Spinner } from "@/components/ui/spinner"

type AgentStateValue = "ready" | "thinking" | "working" | "input" | "done"

/** What each state says when no other words are given. */
const agentStateWords: Record<AgentStateValue, string> = {
  ready: "Ready",
  thinking: "Thinking",
  working: "Working",
  input: "Needs your input",
  done: "Done",
}

type AgentStateProps = Omit<React.ComponentProps<"p">, "children"> & {
  /**
   * Where the agent is. ready: a hairline ring, nothing started. thinking: the ring breathes. working: three
   * voices go round it. input: the one accent disc, your turn. done: the disc filled in ink, the word in pencil.
   * Only thinking and working move, and only while the caller says so.
   */
  state: AgentStateValue
  /** dot (the default): the mark before the word, after the calendar's discs. word: no mark; the word carries it. */
  variant?: "dot" | "word"
  /** Other words for the state ("Reading the brief"). Leave it out for the state's own word. */
  children?: string
}

/** Where an agent is, in one quiet line: a mark and a word. It moves only while the agent thinks or works. */
function AgentState({ state, variant = "dot", children, className, ...props }: AgentStateProps) {
  const word = children || agentStateWords[state]
  const busy = state === "thinking" || state === "working"
  // The mark lands only when the state changes, never on first paint.
  const [seen, setSeen] = React.useState(state)
  const [turned, setTurned] = React.useState(false)
  if (seen !== state) {
    setSeen(state)
    setTurned(true)
  }
  return (
    <Marker
      data-variant={variant === "dot" ? undefined : variant}
      data-state={state}
      data-turned={turned || undefined}
      role="status"
      aria-live="polite"
      aria-busy={busy || undefined}
      className={cn("db-agent", className)}
      {...props}
    >
      {variant === "dot" ? (
        <span key={state} className="db-agent-mark" aria-hidden="true">
          {state === "thinking" ? <Spinner variant="breath" /> : state === "working" ? <Spinner variant="round" /> : null}
        </span>
      ) : null}
      {variant === "word" && busy ? (
        <>
          <span className="db-sr">{word}</span>
          {/* The word spinner is always a status; here the line is, so its own role and voice are taken off. */}
          <Spinner variant="word" label={word} role={undefined} aria-live={undefined} aria-hidden="true" />
        </>
      ) : (
        <span className="db-agent-word">{word}</span>
      )}
    </Marker>
  )
}

export { AgentState, agentStateWords, type AgentStateProps, type AgentStateValue }

@layer components {
  /* ── db-agent ── where an agent is, as a marker's status line: a mark and a word. The mark lives the life of
     the "28 December" calendar's discs: a hairline ring is to come, the one accent disc is now (your turn), a
     filled ink disc is gone by. Only thinking and working move, as the spinner does, while the caller says so. */
  .db-agent { gap: var(--db-space-2); color: var(--db-graphite); }
  .db-agent:is([data-state="thinking"], [data-state="working"], [data-state="input"]) { color: var(--db-ink); }
  .db-agent[data-state="done"] { color: var(--db-pencil); }

  /* The mark stands in a box a capital tall, as the spinner's art does, so the ring and the discs read as one more glyph. */
  .db-agent-mark { position: relative; display: inline-grid; place-items: center; flex: none; inline-size: 0.7em; block-size: 0.7em; }
  .db-agent-mark > .db-dots { display: block; line-height: 0; }
  .db-agent-mark:empty::before { content: ""; inline-size: 0.5em; block-size: 0.5em; box-sizing: border-box; border-radius: 50%; }
  .db-agent[data-state="ready"] .db-agent-mark::before { border: var(--db-hairline) solid var(--db-rule-strong); }
  .db-agent[data-state="input"] .db-agent-mark::before { background: var(--db-accent); }
  .db-agent[data-state="done"] .db-agent-mark::before { background: var(--db-ink); }
  /* What's inked lands: a new disc or ring arrives with one small rebound, only after a change. */
  .db-agent[data-turned] .db-agent-mark::before { animation: db-agent-land var(--db-moderato) var(--db-spiccato) backwards; }
  .db-agent[data-turned] .db-agent-mark > .db-dots { animation: db-arrive var(--db-moderato) var(--db-exhale) backwards; }
  @keyframes db-agent-land { from { scale: 0; } }

  /* word: no mark. The word carries the state: inked letter by letter while busy, the accent when it's your turn. */
  .db-agent[data-variant="word"][data-state="input"] { color: var(--db-accent); }

  @media (forced-colors: active) {
    .db-agent-mark::before { forced-color-adjust: none; }
    .db-agent[data-state="ready"] .db-agent-mark::before { border-color: CanvasText; }
    .db-agent[data-state="input"] .db-agent-mark::before { background: Highlight; }
    .db-agent[data-state="done"] .db-agent-mark::before { background: CanvasText; }
    .db-agent[data-variant="word"][data-state="input"] { color: Highlight; }
  }
}
